    async function sendTuitionMessageBulk(){
      if(!canManageTuition()) return;
      const busyKey=`sendbulk:${tuitionMonthKey()}`;
      if(v20o2IsBusy(busyKey)) return;
      const rows=visibleBillingRows();
      if(!rows.length){toast('Không có học sinh trong danh sách lọc');return}
      if(!confirm(`Gửi hàng loạt cho ${rows.length} học sinh trong danh sách đang lọc?`)) return;
      let ok=0, fail=0;
      try{
        v20o2SetBusy(busyKey,true);
        toast(`Đang gửi ${rows.length} thông tin học phí...`);
        for(const r of rows){
          try{
            await officialFetch('/api/tuition/status',{method:'POST',body:JSON.stringify({studentId:r.student.id,monthKey:tuitionMonthKey(),action:'sent',snapshot:r})});
            ensureTuitionMessages()[paymentKey(r.student.id)]={sent:true,at:new Date().toLocaleString('vi-VN'),by:currentUser.id};
            ok++;
          }catch(e){fail++; console.warn('Không gửi được trạng thái học phí',r.student.id,e)}
        }
        v20o2RerenderTuitionLight();
        toast(fail?`Đã gửi ${ok}/${rows.length}. Lỗi ${fail} học sinh.`:`Đã gửi hàng loạt thông tin học phí`);
      }finally{v20o2SetBusy(busyKey,false)}
    }

    function wrapCanvasLines(ctx,text,maxWidth){
      const paragraphs=String(text||'').split(/\n/); const lines=[];
      paragraphs.forEach(p=>{
        const words=String(p).split(/\s+/).filter(Boolean);
        if(!words.length){lines.push(''); return}
        let line='';
        words.forEach(word=>{
          const test=line?line+' '+word:word;
          if(ctx.measureText(test).width>maxWidth && line){lines.push(line); line=word}else line=test;
        });
        if(line) lines.push(line);
      });
      return lines;
    }
    function drawCanvasText(ctx,text,x,y,maxWidth,lineHeight,color='#1f2937',font='28px Arial',maxLines=99){
      ctx.fillStyle=color; ctx.font=font;
      const lines=wrapCanvasLines(ctx,text,maxWidth).slice(0,maxLines);
      lines.forEach((line,i)=>ctx.fillText(line,x,y+i*lineHeight));
      return y + lines.length*lineHeight;
    }
    function roundedRectPath(ctx,x,y,w,h,r){
      ctx.beginPath();
      ctx.moveTo(x+r,y); ctx.lineTo(x+w-r,y); ctx.quadraticCurveTo(x+w,y,x+w,y+r);
      ctx.lineTo(x+w,y+h-r); ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h);
      ctx.lineTo(x+r,y+h); ctx.quadraticCurveTo(x,y+h,x,y+h-r);
      ctx.lineTo(x,y+r); ctx.quadraticCurveTo(x,y,x+r,y); ctx.closePath();
    }
    function fillRoundRect(ctx,x,y,w,h,r,fill,stroke=''){ roundedRectPath(ctx,x,y,w,h,r); if(fill){ctx.fillStyle=fill; ctx.fill()} if(stroke){ctx.strokeStyle=stroke; ctx.lineWidth=2; ctx.stroke()} }
    function triggerDownload(url,fileName){ const a=document.createElement('a'); a.href=url; a.download=fileName; document.body.appendChild(a); a.click(); a.remove(); }
