    async function login(phone,pw){
      const input=String(phone||'').trim();
      const btn=document.getElementById('loginBtn'); if(btn){btn.disabled=true; btn.textContent='Đang đăng nhập...'}
      try{
        const data=await officialFetch('/api/auth/login',{method:'POST',body:JSON.stringify({phone:input,password:String(pw||'')})});
        currentUser=mapBackendUser(data.user);
        v18dShellKey='';
        v20b4ResetRouteLoadState();
        v20b4ResetSessionMemo();
        v18gClearNetworkCache();
        v18hCleanupLegacyStorage();
        applyOfficialSettings(data.settings);
        route='overview';
        saveUser();

        // V20B.5: sau logout/login trong cùng tab, phải reset cả trạng thái loaded và hash so sánh payload.
        // Nếu hash cũ còn giữ, /api/classes có thể trả dữ liệu đúng nhưng app không apply vì tưởng payload không đổi.
        clearVolatileOfficialState();
        lazyRouteState.core={};
        await ensureCoreData({force:true});
        if(v20aLastCoreLoadError || !(db.classes||[]).length){
          await new Promise(resolve=>setTimeout(resolve,250));
          lazyRouteState.core={};
          await ensureCoreData({force:true});
        }

        render();
        toast(currentUser?.mustChangePassword?'Cần đổi mật khẩu trước khi sử dụng':'Đăng nhập thành công');
        Promise.resolve(ensurePageData(route)).finally(()=>v20cSchedulePrefetch(route));
      }catch(e){
        toast(e.message||'Sai thông tin đăng nhập');
      } finally { if(btn){btn.disabled=false; btn.textContent='Đăng nhập'} }
    }

    async function logout(){
      try{await officialFetch('/api/auth/logout',{method:'POST',body:'{}'});}catch(e){}
      v20b4ResetRouteLoadState();
      v20b4ResetSessionMemo();
      v18gClearNetworkCache();
      clearVolatileOfficialState();
      currentUser=null;
      v18dShellKey='';
      localStorage.removeItem('msgiang_v48_user');
      render();
    }
    function reset(){localStorage.removeItem('msgiang_v48_data'); db=JSON.parse(JSON.stringify(SEED)); v18hSaveCompactLocalDb(); toast('Đã reset dữ liệu'); render()}
    function render(){
      try{
        if(!currentUser) return renderLogin();
        if(currentUser.mustChangePassword) return renderForceChangePassword();
        renderApp();
      }catch(e){
        console.error('Render error',e);
        root.innerHTML=`<div class="app"><main class="main" style="padding:32px"><div class="blockedBox"><h2>⚠️ Lỗi giao diện</h2><p>${h(e.message||'Có lỗi khi mở trang này')}</p><button class="btn primary" onclick="route='overview';saveUser();render()">Về tổng quan</button></div></main></div>`;
      }
    }
    function renderLogin(){root.innerHTML=`<div class="login"><div class="loginHero"><div><img src="/v15/assets/asset-aa296a04fdb9.png" alt="Ms.Giang English"><h1>Quản lý trung tâm tiếng Anh mượt hơn, rõ hơn.</h1><p>Hệ thống quản lý lớp học, lịch dạy, điểm danh, học bù, học phí, đánh giá và thư viện tài liệu cho Ms.Giang English Center.</p></div><div class="pill red">✨ Ms.Giang English Center</div></div><div class="loginCard"><h2>Đăng nhập</h2><label>Số điện thoại / tài khoản<input id="lgPhone" class="input" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Nhập tài khoản"></label><label>Mật khẩu<input id="lgPw" class="input" type="password" autocomplete="off" placeholder="Nhập mật khẩu"></label><button id="loginBtn" class="btn primary" style="width:100%" onclick="login(document.getElementById('lgPhone').value,document.getElementById('lgPw').value)">Đăng nhập</button></div></div>`}
    function quick(phone){toast('Chức năng đăng nhập nhanh đã tắt trên bản production')}
    function renderApp(){
      if(currentUser?.mustChangePassword) return renderForceChangePassword();
      const nav=navItems(); const unread=0;
      if(!nav.some(n=>n[0]===route)) route='overview';
      const shellKey=v18dShellKeyFor(nav);

      // V18D: Khi app shell đã có sẵn và quyền/nav không đổi, chỉ render lại phần nội dung.
      // Giữ nguyên sidebar/topbar/bottomNav để đổi tab và thao tác trong app mượt hơn.
      if(v18dShellKey===shellKey && v18dRenderPageOnly(nav)) return;

      v18dShellKey=shellKey;
      const initialPage=page();
      root.innerHTML=`<div class="drawerOverlay" id="drawerOverlay" onclick="closeDrawer()"></div><div class="app"><aside class="sidebar" id="sidebar"><div class="logoBox"><img src="/v15/assets/asset-aa296a04fdb9.png" alt="logo"></div><div class="roleChip">${roleLabel()}</div><nav class="nav">${v18dNavMarkup(nav)}</nav></aside><main class="main"><header class="topbar"><div class="topbarLeft"><button class="hamb" onclick="openDrawer()">☰</button><span class="mobileBrand">Ms.Giang</span></div><div class="userpill"><div class="avatar">${isParent()?'👪':isAdmin()?'👑':isManager()?'🧭':'👩‍🏫'}</div><div class="userText"><b>${currentUser.name}</b><div class="mini">${roleLabel()}</div></div><button class="logout" onclick="logout()">Thoát</button></div></header><section class="content"><div class="page v20dPageReady" id="appPage">${initialPage}</div></section><nav class="bottomNav">${v18dBottomNavMarkup(nav)}</nav></main></div>`;
      const pageEl=document.getElementById('appPage');
      if(pageEl) pageEl.__v20dLastHtml=initialPage;
    }
    function openDrawer(){document.getElementById('sidebar')?.classList.add('open');document.getElementById('drawerOverlay')?.classList.add('show')}
    function closeDrawer(){document.getElementById('sidebar')?.classList.remove('open');document.getElementById('drawerOverlay')?.classList.remove('show')}
    function toggleNotif(){notifOpen=!notifOpen; renderApp()}
    function page(){
      try{
        if(isRouteWaitingForData(route)){
          ensureRouteData(route);
          const names={overview:'tổng quan',classes:'lớp học',schedule:'lịch dạy',makeup:'học bù',attendance:'điểm danh',homework:'thư viện bài tập',evaluation:'đánh giá học sinh',tuition:'học phí',teachers:'giáo viên',settings:'cài đặt'};
          return routeLoadingMarkup(`Đang tải ${names[route]||'dữ liệu'}...`);
        }
        return ({overview,classes:classesPage,schedule:schedulePage,attendance:attendancePage,homework:homeworkPage,evaluation:evaluationPage,tuition:tuitionPage,makeup:makeupPage,teachers:teachersPage,settings:settingsPage}[route]||overview)()
      }catch(e){
        console.error('Page render error',route,e);
        return `<div class="blockedBox"><h2>⚠️ Không mở được trang</h2><p>${h(e.message||'Có lỗi khi tải trang này')}</p><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn primary" onclick="route='overview';saveUser();render()">Về tổng quan</button><button class="btn ghost" onclick="runHealthCheck()">Kiểm tra hệ thống</button></div></div>`
      }
    }

    function overview(){
      const cls=classesForUser(); const students=cls.reduce((s,c)=>s+c.students.length,0); const pending=teacherPendingGrades(); const bill=visibleBillingRows().reduce((s,r)=>s+r.amount,0);
      const tuitionStat = canViewTuition()?`<div class="stat" style="--i:3"><div class="statIcon greengrad">💰</div><div><h3>Học phí hiển thị</h3><strong style="font-size:24px">${fmt.format(bill)}</strong><small>${isParent()?(visibleBillingRows()[0]?.paid?'Đã đóng học phí':'Chưa đóng học phí'):'theo quyền xem'}</small></div></div>`:`<div class="stat" style="--i:3"><div class="statIcon greengrad">🔒</div><div><h3>Học phí</h3><strong style="font-size:20px">Không hiển thị</strong><small>Giáo viên không có quyền xem</small></div></div>`;
      return `${parentChildSelector()}<div class="hero"><div class="heroCard"><h1>Xin chào, ${currentUser.name} 👋</h1><p>${isParent()?'Theo dõi bài tập, đánh giá, học phí và lịch học bù của từng bé.':isManager()?'Tổng quan cả việc dạy của bạn và công việc quản lí cần xử lý.':isTA()?'Theo dõi lớp trợ giảng, điểm danh, học bù và đánh giá học sinh.':isTeacher()?'Theo dõi lớp dạy, bài tập cần chấm và đánh giá học sinh.':'Quản lý toàn bộ lớp học, học phí, bài tập và vận hành trung tâm.'}</p></div><div class="heroArt"><span>📚</span><span>✏️</span><div class="speech">Let's<br>Learn!</div><span>⭐</span><span>🔤</span></div></div><div class="statGrid"><div class="stat" style="--i:0"><div class="statIcon redgrad">🏫</div><div><h3>Lớp nhìn thấy</h3><strong>${cls.length}</strong><small>${isTA()?'Chỉ lớp mình trợ giảng':isTeacher()?'Chỉ lớp mình dạy':'Theo quyền tài khoản'}</small></div></div><div class="stat" style="--i:1"><div class="statIcon bluegrad">👦</div><div><h3>Học sinh</h3><strong>${students}</strong><small>Từ danh sách lớp thực tế</small></div></div><div class="stat" style="--i:2"><div class="statIcon yellowgrad">📝</div><div><h3>Bài cần chấm</h3><strong>${pending}</strong><small>Speaking/Writing</small></div></div>${tuitionStat}</div><div class="grid2"><div class="panel"><div class="panelHead"><h2>Việc cần xử lý</h2><button class="linkBtn" onclick="go('schedule')">Xem lịch</button></div><div class="todo">${quickTodos().map((t,i)=>`<div class="todoItem" style="--i:${i}"><div><b>${t.title}</b><p>${t.desc}</p></div><button class="btn primary" onclick="go('${t.route}')">Mở</button></div>`).join('')}</div></div><div class="panel"><div class="panelHead"><h2>Thông báo mới</h2><button class="linkBtn" onclick="go('notifications')">Tất cả</button></div>${notifications().slice(0,4).map((n,i)=>`<div class="notifItem" style="animation-delay:${i*70}ms"><div class="nIcon">${n.icon}</div><div><b>${n.title}</b><p style="margin:4px 0;color:var(--muted)">${n.desc}</p></div></div>`).join('')}</div></div>`
    }


    function quickTodos(){ if(isParent())return [{title:'Làm bài tập mới',desc:'Có bài Listening cần hoàn thành.',route:'homework'},{title:'Xem đánh giá tháng',desc:'Biểu đồ năng lực và nhận xét mới.',route:'evaluation'},{title:'Kiểm tra học phí',desc:'Trạng thái đã đóng/chưa đóng của bé đang chọn.',route:'tuition'}]; if(isTeachingUser()&&!isManager())return [{title:'Chấm bài Speaking/Writing',desc:`${teacherPendingGrades()} bài đang chờ chấm.`,route:'homework'},{title:'Điểm danh lớp hôm nay',desc:'Hoàn thành điểm danh trực tiếp.',route:'attendance'},{title:'Xếp học bù',desc:'Giáo viên/TA được xếp học bù cho lớp chưa dạy.',route:'schedule'}]; if(isManager())return [{title:'Xếp học bù',desc:'Sắp xếp học sinh nghỉ sang buổi phù hợp.',route:'schedule'},{title:'Gửi học phí phụ huynh',desc:'Gửi thông tin học phí ngay trong bảng học phí.',route:'tuition'},{title:'Chấm bài lớp mình dạy',desc:`${teacherPendingGrades()} bài cần xử lý.`,route:'homework'}]; return [{title:'Phân quyền giáo viên',desc:'Tạo giáo viên, phân quyền và gán vào lớp.',route:'teachers'},{title:'Kiểm tra vận hành lớp',desc:'Lớp, lịch dạy, giáo viên và học sinh.',route:'classes'},{title:'Tổng hợp học phí',desc:'Xem toàn bộ học phí tháng.',route:'tuition'},{title:'Theo dõi đánh giá',desc:'Kiểm tra đánh giá học sinh.',route:'evaluation'}]}


    
function teacherRoleValue(t){return t.roles?.includes('admin')?'admin':t.roles?.includes('manager')?'manager':t.roles?.includes('ta')?'ta':'teacher'}
    function teacherRoleLabel(t){const v=teacherRoleValue(t); return v==='admin'?'Admin':v==='manager'?'Quản lí':v==='ta'?'TA':'Giáo viên'}
    function teacherRoleClasses(t){const v=teacherRoleValue(t); return v==='admin'?'red':v==='manager'?'blue':v==='ta'?'purple':'green'}
    function classesOfTeacher(t){return db.classes.filter(c=>c.teacherId===t.id || c.taId===t.id || c.teacher===t.name || c.ta===t.name)}

    function roleChoiceMarkup(active='teacher',prefix='teacherRoleChoice',allowAdmin=isAdmin()){
      const roles=[
        ['teacher','👩‍🏫','Giáo viên','Điểm danh, xem lớp được phân công, thư viện và đánh giá học sinh.'],
        ['ta','🧑‍🏫','TA','Trợ giảng: điểm danh, xếp học bù, đánh giá và sửa đánh giá lớp được gán.'],
        ['manager','🛡️','Quản lí','Quản lý lớp, lịch, học bù, học phí, giáo viên và dữ liệu vận hành.'],
        ['admin','👑','Admin','Toàn quyền: cài đặt, phân quyền, tạo tài khoản và quản trị hệ thống.']
      ].filter(r=>allowAdmin || r[0]!=='admin');
      return `<div class="teacherPermGrid">${roles.map(r=>`<div class="roleChoice ${active===r[0]?'active':''}" onclick="selectTeacherRole('${prefix}','${r[0]}')"><input type="radio" name="${prefix}" value="${r[0]}" ${active===r[0]?'checked':''} style="display:none"><b>${r[1]} ${r[2]}</b><small>${r[3]}</small></div>`).join('')}</div>`
    }
    function selectTeacherRole(name,value){
      document.querySelectorAll(`input[name="${name}"]`).forEach(i=>{i.checked=i.value===value});
      document.querySelectorAll(`input[name="${name}"]`).forEach(i=>i.closest('.roleChoice')?.classList.toggle('active',i.checked));
    }
    function selectedTeacherRole(name,def='teacher'){
      return document.querySelector(`input[name="${name}"]:checked`)?.value || def;
    }

    function teacherRoleLegend(){
      return `<div class="teacherRoleLegend">
        <div class="miniRole"><b>👩‍🏫 Giáo viên</b>Chỉ thấy lớp được gán. Không thấy học phí và không quản lý tài khoản.</div>
        <div class="miniRole"><b>🧑‍🏫 TA</b>Điểm danh, xếp học bù, đánh giá và sửa đánh giá ở lớp được gán làm TA.</div>
        <div class="miniRole"><b>🛡️ Quản lí</b>Thấy toàn bộ dữ liệu vận hành, học phí, lịch, điểm danh và giáo viên.</div>
        <div class="miniRole"><b>👑 Admin</b>Toàn quyền, bao gồm cài đặt hệ thống và phân quyền cấp cao.</div>
      </div>`
    }

    function teachersPage(){
      if(!(isAdmin()||isManager())) return `<div class="blockedBox"><h2>🔒 Không có quyền truy cập</h2></div>`;
      const rows=[...db.teachers].sort((a,b)=>a.name.localeCompare(b.name,'vi'));
      const managerCount=rows.filter(t=>t.roles?.includes('manager')).length;
      const taCount=rows.filter(t=>t.roles?.includes('ta')).length;
      const adminCount=rows.filter(t=>t.roles?.includes('admin')).length;
      return `<div class="screenTitle"><div><h1>Giáo viên</h1><p>Quản lý thông tin, phân quyền, tài khoản đăng nhập và lớp dạy.</p></div><button class="btn primary" onclick="openTeacherModal()">+ Tạo giáo viên</button></div>
      ${teacherRoleLegend()}
      <div class="statGrid"><div class="stat"><div class="statIcon redgrad">👩‍🏫</div><div><h3>Tổng giáo viên</h3><strong>${rows.length}</strong><small>đang có</small></div></div><div class="stat"><div class="statIcon bluegrad">🛡️</div><div><h3>Quản lí</h3><strong>${managerCount}</strong><small>có quyền vận hành</small></div></div><div class="stat"><div class="statIcon greengrad">🧑‍🏫</div><div><h3>TA</h3><strong>${taCount}</strong><small>trợ giảng được gán lớp</small></div></div><div class="stat"><div class="statIcon redgrad">👑</div><div><h3>Admin</h3><strong>${adminCount}</strong><small>toàn quyền</small></div></div></div>
      <div class="grid3">${rows.map((t,i)=>teacherCard(t,i)).join('')}</div>`
    }

    function teacherCard(t,i){
      const cls=classesOfTeacher(t);
      const active=t.status!=='inactive';
      return `<div class="teacherCard" style="--i:${i}" onclick="openTeacherDetail('${t.id}')"><div class="teacherTop"><div class="teacherTopLeft"><div class="teacherAvatar">${(t.name||'T').split(' ').slice(-1)[0][0]||'T'}</div><div><h3 style="margin:0">${t.name}</h3><div class="mini">${t.phone||'Chưa có SĐT'}${t.email?` • ${t.email}`:''}</div></div></div><span class="pill ${teacherRoleClasses(t)}">${teacherRoleLabel(t)}</span></div>
      <div class="teacherMeta"><span class="pill gray">${cls.length} lớp</span><span class="pill ${active?'green':'gray'}">${active?'Đang hoạt động':'Tạm khóa'}</span></div>
      <div class="teacherClassList">${cls.length?cls.slice(0,8).map(c=>`<span class="sessionTag">${c.name}</span>`).join(''):'<span class="mini">Chưa được gán lớp</span>'}</div></div>`
    }

    function openTeacherModal(){
      modal(`<div class="modalHead"><h2>+ Tạo tài khoản giáo viên</h2><button class="close" onclick="closeModal()">×</button></div>
      <div class="teacherDetailHeader"><div class="teacherAvatar">+</div><div><h3 style="margin:0">Tạo giáo viên / quản lí mới</h3><p class="mini">Hệ thống sẽ tạo tài khoản đăng nhập thật và mật khẩu tạm 6 số. Người dùng sẽ phải đổi mật khẩu sau khi đăng nhập.</p></div></div>
      <div class="formGrid"><label>Họ tên<input id="teacherName" class="input" placeholder="VD: Ms Linh"></label><label>Số điện thoại / tài khoản<input id="teacherPhone" class="input" placeholder="VD: 0987654321"></label><label>Email<input id="teacherEmail" class="input" placeholder="tuỳ chọn"></label><label>Trạng thái<input class="input" value="Hoạt động" disabled></label></div>
      <div class="teacherPermPanel"><b>Phân quyền</b>${roleChoiceMarkup('teacher','teacherRoleChoice',isAdmin())}</div>
      <div style="text-align:right;margin-top:18px"><button class="btn ghost" onclick="closeModal()">Hủy</button> <button class="btn primary" onclick="saveTeacherFromModal()">Tạo tài khoản</button></div>`)
    }

    async function saveTeacherFromModal(){
      const name=(document.getElementById('teacherName')?.value||'').trim();
      const phone=normalizePhone(document.getElementById('teacherPhone')?.value||'');
      const email=(document.getElementById('teacherEmail')?.value||'').trim();
      let role=selectedTeacherRole('teacherRoleChoice','teacher');
      if(!isAdmin() && role==='admin') role='manager';
      if(!name || !phone){toast('Nhập đủ tên và số điện thoại');return}
      try{
        const data=await officialFetch('/api/teachers',{method:'POST',body:JSON.stringify({name,phone,email,role})});
        db.teachers = db.teachers.filter(t=>t.id!==data.teacher.id);
        db.teachers.push(data.teacher);
        v20bAfterMutation(['teachers']);
        save(); route='teachers'; saveUser(); render();
        showTempPasswordModal('Đã tạo tài khoản',data.teacher.phone,data.tempPassword,'render');
      }catch(e){toast(e.message||'Không tạo được giáo viên')}
    }

    function openTeacherDetail(id){
      if(!(isAdmin()||isManager())) return;
      const t=teacherById(id); if(!t?.id) return;
      const cls=classesOfTeacher(t);
      const role=teacherRoleValue(t);
      const assignmentRole=role==='ta'?'ta':'teacher';
      const activeClassOptions=sortClassesByGrade(db.classes).filter(c=>!isClassEnded(c)).filter(c=>assignmentRole==='ta'?c.taId!==t.id:c.teacherId!==t.id);
      const classOptions=activeClassOptions.map(c=>`<option value="${c.id}">${c.name}</option>`).join('');
      modal(`<div class="modalHead"><h2>Thông tin giáo viên</h2><button class="close" onclick="closeModal()">×</button></div>
      <div class="teacherDetailHeader"><div class="teacherAvatar">${(t.name||'T').split(' ').slice(-1)[0][0]||'T'}</div><div><h3 style="margin:0">${t.name}</h3><p class="mini">Tài khoản: <b>${t.phone||'-'}</b></p><span class="pill ${teacherRoleClasses(t)}">${teacherRoleLabel(t)}</span></div></div>
      <div class="teacherPopupGrid"><label>Họ tên<input id="editTeacherName" class="input" value="${h(t.name||'')}"></label><label>Số điện thoại / tài khoản<input id="editTeacherPhone" class="input" value="${h(t.phone||'')}"></label><label>Email<input id="editTeacherEmail" class="input" value="${h(t.email||'')}"></label><label>Trạng thái<select id="editTeacherStatus" class="input"><option value="active" ${t.status!=='inactive'?'selected':''}>Đang hoạt động</option><option value="inactive" ${t.status==='inactive'?'selected':''}>Tạm khóa</option></select></label></div>
      <div class="teacherPermPanel"><b>Phân quyền</b>${roleChoiceMarkup(role,'editTeacherRoleChoice',isAdmin())}</div>
      <div class="teacherClassBox"><b>Lớp đang phụ trách</b>${cls.length?cls.map(c=>`<div class="teacherClassRow"><span><b>${c.name}</b><span class="mini"> • ${c.time||'Chưa có lịch'}</span>${isClassEnded(c)?'<span class="pill gray" style="margin-left:8px">Đã kết thúc • khóa</span>':''}</span>${isClassEnded(c)?'<span class="mini">Chỉ xem lịch sử</span>':`<button class="btn ghost miniCardBtn" onclick="removeTeacherFromClass('${t.id}','${c.id}','${assignmentRole}')">Bỏ gán</button>`}</div>`).join(''):'<div class="mini" style="margin-top:8px">Chưa được gán lớp</div>'}
      <div class="teacherAssignBox"><label>Gán thêm lớp<select id="teacherAssignClass" class="input"><option value="">-- Chọn lớp đang học --</option>${classOptions}</select></label><button class="btn primary" onclick="const v=document.getElementById('teacherAssignClass').value;if(v)assignTeacherToClass('${t.id}',v,'${assignmentRole}')">Gán lớp</button></div></div>
      <div style="text-align:right;margin-top:18px"><button class="btn ghost" onclick="closeModal()">Đóng</button> <button class="btn ghost" onclick="resetTeacherPassword('${t.id}')">Reset mật khẩu</button> <button class="btn ghost dangerMini" onclick="deleteTeacher('${t.id}')">Xóa giáo viên</button> <button class="btn primary" onclick="saveTeacherDetail('${t.id}')">Lưu thông tin</button></div>`)
    }

    async function saveTeacherDetail(id){
      if(!(isAdmin()||isManager())) return;
      const t=teacherById(id); if(!t?.id) return;
      const name=(document.getElementById('editTeacherName')?.value||'').trim();
      const phone=normalizePhone(document.getElementById('editTeacherPhone')?.value||'');
      const email=(document.getElementById('editTeacherEmail')?.value||'').trim();
      const status=document.getElementById('editTeacherStatus')?.value||'active';
      let role=selectedTeacherRole('editTeacherRoleChoice',teacherRoleValue(t));
      if(!isAdmin() && role==='admin') role='manager';
      if(!name || !phone){toast('Nhập đủ tên và số điện thoại');return}
      try{
        const data=await officialFetch('/api/teachers',{method:'PATCH',body:JSON.stringify({id,name,phone,email,status,role})});
        db.teachers=db.teachers.map(x=>x.id===id?data.teacher:x);
        db.classes.forEach(c=>{if(c.teacherId===id){c.teacher=data.teacher.name}; if(c.taId===id){c.ta=data.teacher.name}});
        v20bAfterMutation(['teachers','core']);
        save(); toast('Đã lưu giáo viên và phân quyền'); openTeacherDetail(id);
      }catch(e){toast(e.message||'Không lưu được giáo viên')}
    }

    async function resetTeacherPassword(teacherId){
      const t=teacherById(teacherId); if(!t?.id) return;
      try{
        const data=await officialFetch(`/api/teachers/${teacherId}/reset-password`,{method:'POST',body:'{}'});
        showTempPasswordModal('Đã reset mật khẩu',data.phone||t.phone,data.tempPassword,'render');
      }catch(e){toast(e.message||'Không reset được mật khẩu')}
    }

    async function assignTeacherToClass(teacherId,classId,assignmentRole='teacher'){
      if(!(isAdmin()||isManager())) return;
      const t=teacherById(teacherId), c=classById(classId);
      if(!t?.id || !c?.id) return;
      if(isClassEnded(c)){toast('Lớp đã kết thúc, không thể gán giáo viên/TA.');return}
      if(assignmentRole==='ta' && String(c.teacherId||'')===String(teacherId)){toast('Một người không nên vừa là giáo viên chính vừa là TA của cùng lớp.');return}
      if(assignmentRole!=='ta' && String(c.taId||'')===String(teacherId)){toast('Một người không nên vừa là giáo viên chính vừa là TA của cùng lớp.');return}
      try{
        await officialFetch(`/api/teachers/${teacherId}/classes`,{method:'POST',body:JSON.stringify({classId,action:'assign',assignmentRole})});
        if(assignmentRole==='ta'){c.ta=t.name; c.taId=t.id}else{c.teacher=t.name; c.teacherId=t.id}
        v20bAfterMutation(['core','teachers']); save(); toast(`Đã gán ${t.name} vào ${c.name}`); openTeacherDetail(teacherId);
      }catch(e){toast(e.message||'Không gán được lớp')}
    }

    async function removeTeacherFromClass(teacherId,classId,assignmentRole='teacher'){
      if(!(isAdmin()||isManager())) return;
      const c=classById(classId); const t=teacherById(teacherId); if(!c?.id||!t?.id) return;
      if(isClassEnded(c)){toast('Lớp đã kết thúc, không thể bỏ gán giáo viên/TA.');return}
      try{
        await officialFetch(`/api/teachers/${teacherId}/classes`,{method:'POST',body:JSON.stringify({classId,action:'remove',assignmentRole})});
        if(assignmentRole==='ta' && (c.taId===teacherId || c.ta===t.name)){c.ta=''; c.taId=null}
        if(assignmentRole!=='ta' && (c.teacherId===teacherId || c.teacher===t.name)){c.teacher=''; c.teacherId=null}
        v20bAfterMutation(['core','teachers']);
        save(); toast('Đã bỏ gán lớp'); openTeacherDetail(teacherId);
      }catch(e){toast(e.message||'Không bỏ gán được lớp')}
    }


    async function deleteTeacher(teacherId){
      if(!(isAdmin()||isManager())) return;
      const t=teacherById(teacherId); if(!t?.id) return;
      const cls=classesOfTeacher(t);
      const ended=cls.filter(isClassEnded);
      if(ended.length){toast('Không thể xóa nhân sự đang nằm trong lớp đã kết thúc. Cần giữ nguyên lịch sử lớp.');return}
      const ok=confirm(`Xóa giáo viên/TA ${t.name}?\n\nTài khoản đăng nhập sẽ bị xóa. ${cls.length} lớp đang học đang gán sẽ được bỏ giáo viên/TA.`);
      if(!ok) return;
      try{
        await officialFetch('/api/teachers',{method:'DELETE',body:JSON.stringify({id:teacherId})});
        db.teachers=db.teachers.filter(x=>x.id!==teacherId);
        db.users=(db.users||[]).filter(u=>normalizePhone(u.phone)!==normalizePhone(t.phone));
        db.classes.forEach(c=>{if(c.teacherId===teacherId || c.teacher===t.name){c.teacher=''; c.teacherId=null}; if(c.taId===teacherId || c.ta===t.name){c.ta=''; c.taId=null}});
        v20bAfterMutation(['teachers','core']);
        save(); closeModal(); toast('Đã xóa giáo viên và tài khoản liên quan'); render();
      }catch(e){toast(e.message||'Không xóa được giáo viên')}
    }

